package tn.supcom.greenpilot.api.controllers.repositories;

import jakarta.data.repository.BasicRepository;
import jakarta.data.repository.Repository;
import tn.supcom.greenpilot.api.entities.Incident;
import java.util.List;

/** Jakarta Data repository - implementation generated by Eclipse JNoSQL. */
@Repository
public interface IncidentRepository extends BasicRepository<Incident, String> {

    /** Finds a site's incidents with any of the supplied statuses, newest first. */
    List<Incident> findBySiteIdAndStatusInOrderByLastSeenAtDesc(String siteId, List<String> statuses);

    List<Incident> findBySiteIdAndPlantIdAndStatusIn(String siteId, String plantId, List<String> status);
}
